/// <summary>
/// Utility functions for monitoring and telemetry.
/// </summary>
internal class SysEnvironmentUtil
{
}

Method.Source:
    /// <summary>
    /// Determine the environment mode
    /// </summary>
    /// <returns>Dev / TST / Prod</returns>
    public static EnvironmentMode getEnvironmentMode()
    {
        SysEnvironmentModeMap environmentMap;

        try
        {
            SysEnvironmentId lcsEnvironmentId = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment().LCS.LCSEnvironmentId.ToString();

            select firstonly environmentMap
                where environmentMap.SysEnvironmentId == lcsEnvironmentId;
        }
        catch
        {
            return EnvironmentMode::Dev;
        }

        return (environmentMap.RecId == 0 ? EnvironmentMode::Dev : environmentMap.EnvironmentMode);
    }

    /// <summary>
    /// Gets the location from the SysIntegrationRegistry table based on the specified application name.
    /// </summary>
    /// <param name = "_appName">The application name to search for.</param>
    /// <returns>The URL of the application name.</returns>
    public static URL getLocationByAppName(str _appName)
    {
        SysIntegrationRegistry registry;

        select firstonly registry
            where registry.SysApplicationName == _appName
            && registry.EnvironmentMode == SysEnvironmentUtil::getEnvironmentMode();

        return registry.SysAppURI;
    }
